from q1_3 import Q, mc, tf, out, blank

# ---------------- Section 4: OOP, DDD & Testing ----------------
S = 4
mc(S, "4.1", 1, "Which command turns a class library into a NuGet package?", ["dotnet build", "dotnet pack", "dotnet publish", "dotnet nuget"], 1, "dotnet pack makes a .nupkg.")
mc(S, "4.1", 2, "ProjectReference vs PackageReference:", ["Same thing", "ProjectReference uses source in the same solution; PackageReference uses a versioned .nupkg", "PackageReference is faster to build", "ProjectReference needs nuget.org"], 1, "Packages are for sharing across solutions and teams; versions matter.")
blank(S, "4.1", 2, "Tell NuGet about a local folder feed (nuget.config).", "<add key=\"local\" value=\"../____\" />", ["LocalNuGetFeed"], "4.1's ConsumerApp finds the package in ../LocalNuGetFeed.")
mc(S, "4.1", 2, "Version=\"[2.0.0]\" in a PackageReference means...", ["2.0.0 or higher", "exactly 2.0.0", "below 2.0.0", "any 2.x"], 1, "Square brackets = exact. Version=\"2.0.0\" alone means 2.0.0 or higher.")
blank(S, "4.1", 2, "Make an extension method on string.", "public static string ToUrlSlug(____ string text)\n{\n}", ["this"], "The 'this' on the first parameter makes \"Hello\".ToUrlSlug() possible.")
mc(S, "4.2", 1, "What is a value object?", ["An object with an Id", "Defined only by its values, immutable, e.g. Money", "A database row", "A static class"], 1, "Two Money(10, \"USD\") are the same thing; they have no identity.")
mc(S, "4.2", 2, "What is an aggregate?", ["A LINQ method", "A cluster of objects changed only through one root that enforces the rules", "A database view", "A collection type"], 1, "BankAccountAggregate: you can't change the balance except through Deposit/Withdraw.")
mc(S, "4.2", 2, "Domain events are named...", ["In the future tense (WillOpen)", "In the past tense (AccountOpened)", "After the database table", "Anything"], 1, "An event is a fact that already happened.")
mc(S, "4.2", 2, "Why use a factory method like BankAccount.Open(...) with a private constructor?", ["It's faster", "Callers can't skip the rules that Open checks", "Required by EF", "To allow inheritance"], 1, "The only way in goes through the checks.")
tf(S, "4.2", 2, "A record whose check is only in its constructor can be made invalid with 'with'.", True, "4.2's MoneyPositionalVariation: positional with { Amount = -5 } gives -5.")
mc(S, "4.2", 2, "A hand-written fake repository in tests is...", ["A mocking library", "A small class implementing the interface with an in-memory list", "The real database", "Not allowed"], 1, "4.2 uses ~10-line fakes instead of Moq: anyone can read them.")
mc(S, "4.2", 1, "In xUnit, which attribute marks a test with no parameters?", ["[Test]", "[Fact]", "[TestMethod]", "[Theory]"], 1, "[Theory] + [InlineData] for parameterised tests.")
blank(S, "4.2", 1, "Assert that code throws.", "Assert.____<InsufficientFundsException>(() => account.Withdraw(500m));", ["Throws"], "Assert.Throws<T> fails if nothing (or something else) is thrown.")
blank(S, "4.2", 2, "Run the same test with several inputs.", "[____]\n[InlineData(5)]\n[InlineData(10)]\npublic void Works(int amount)", ["Theory"], "[Theory] runs once per [InlineData].")
mc(S, "4.2", 2, "AddSingleton vs AddScoped in a web app:", ["Same", "Singleton: one for the app's life; Scoped: one per request", "Scoped: one forever", "Singleton: one per request"], 1, "Transient = a new one every time it's asked for.")
mc(S, "4.3", 2, "Playwright tests do what?", ["Unit-test methods", "Drive a real browser against the running app", "Benchmark code", "Mock HTTP"], 1, "4.3 opens 3.1's pages in Chromium and clicks through them.")
blank(S, "4.3", 2, "Wait until an element has the right text (Playwright).", "await ____(page.Locator(\"h1\")).ToHaveTextAsync(\"Products\");", ["Expect"], "Expect(...) assertions retry until true or timeout, unlike a one-time read.")
mc(S, "4.3", 3, "Which locator style is most robust?", ["CSS by position (div:nth-child(3))", "GetByRole(AriaRole.Button, new() { Name = \"Save\" })", "XPath with indexes", "Pixel coordinates"], 1, "Role + accessible name survives layout changes.")
tf(S, "4.3", 2, "WebApplicationFactory can start the app in the test process without a real port.", True, "That's for in-memory HTTP tests; Playwright needs a real server, so 4.3 starts one.")
mc(S, "4.2", 3, "PositivePositive / PositiveNegative / NegativeNegative in this repo mean...", ["Three random tests", "Works / valid-but-edge case / invalid input", "Fast / slow / skipped", "Unit / integration / e2e"], 1, "Every behaviour gets all three.")

# ---------------- Section 5: Concurrency, Async & Memory ----------------
S = 5
mc(S, "5.1", 1, "What does await do?", ["Blocks the thread until done", "Frees the thread and continues later when the task finishes", "Starts a new thread", "Makes the code synchronous"], 1, "The method pauses; the thread can do other work meanwhile.")
out(S, "5.1", 3, "int count = 0;\nParallel.For(0, 100_000, _ => count++);\nConsole.WriteLine(count == 100_000);", ["Always True", "Usually False", "Compile error", "Always throws"], 1, "count++ is read-add-write; threads overwrite each other. Use Interlocked.Increment or lock.")
blank(S, "5.1", 2, "Add 1 safely from many threads.", "Interlocked.____(ref count);", ["Increment"], "An atomic read-add-write.")
blank(S, "5.1", 1, "Protect a block so only one thread runs it at a time.", "____ (gate)\n{\n    total += amount;\n}", ["lock"], "lock(gate) { } lets one thread in at a time.")
mc(S, "5.1", 2, "Why copy the loop variable before starting a thread in a for loop?", ["Speed", "All lambdas share ONE for-loop variable and see its final value", "Required by Thread", "To avoid boxing"], 1, "for (int i...) has one i; foreach gives a new variable each round (since C# 5).")
mc(S, "5.1", 2, "Task.WhenAll(tasks) ...", ["Runs them one by one", "Finishes when every task has finished", "Returns the first result", "Cancels the others"], 1, "Task.WhenAny finishes at the first.")
mc(S, "5.1", 2, "event vs a public delegate field:", ["Same", "Outside code can only += / -= an event, not invoke or overwrite it", "event is faster", "Delegates can't have parameters"], 1, "With a field, any caller could set it to null or fire it.")
blank(S, "5.1", 2, "Call an event only if someone subscribed.", "Finished____.Invoke(this, args);", ["?"], "Finished?.Invoke(...) does nothing when there are no subscribers.")
tf(S, "5.1", 2, "async void should only be used for event handlers.", True, "Exceptions from async void can't be caught by the caller; return Task instead.")
mc(S, "5.2", 2, "A bounded channel with FullMode = Wait makes the producer...", ["Drop items", "Wait when the channel is full (backpressure)", "Throw", "Grow the channel"], 1, "That stops a fast producer from filling memory.")
blank(S, "5.2", 2, "Read everything from a channel until it's completed.", "await foreach (string line in channel.Reader.____())\n{\n}", ["ReadAllAsync"], "Ends when the writer calls Complete() and the channel is empty.")
blank(S, "5.2", 2, "Tell readers no more items are coming.", "channel.Writer.____();", ["Complete"], "Without it, ReadAllAsync waits forever.")
mc(S, "5.2", 3, "ArrayPool<byte>.Shared.Rent(4096) — what must you do after?", ["Nothing", "Return(buffer) so it can be reused", "Dispose it", "Set it to null"], 1, "Rent/Return reuses arrays and avoids garbage collection work.")
mc(S, "5.2", 3, "When is ValueTask better than Task?", ["Always", "When the result is often already available (no real async work)", "For long-running work", "Never"], 1, "It avoids allocating a Task on the fast path.")
mc(S, "5.3", 1, "Benchmarks must run in...", ["Debug", "Release", "Any mode", "Docker"], 1, "Debug builds aren't optimised; the numbers would be meaningless.")
blank(S, "5.3", 2, "Show allocations in a BenchmarkDotNet run.", "[____]\npublic class LookupBenchmark", ["MemoryDiagnoser"], "Adds the Allocated column.")
mc(S, "5.3", 3, "In 5.3, reading string.Length via PropertyInfo.GetValue each time was about how much slower than direct?", ["2x", "10x", "80x+", "Same"], 2, "~12 ns vs ~0.15 ns, plus 24 B allocated (boxing the int).")
mc(S, "5.3", 2, "A benchmark is only fair if...", ["It runs once", "Every method computes the same answer", "It uses Stopwatch", "It runs in Debug"], 1, "5.3's tests check all variations return the same value.")
mc(S, "5.4", 1, "IAsyncEnumerable<T> is looped with...", ["foreach", "await foreach", "for", "Parallel.ForEach"], 1, "Each item can arrive after an await.")
blank(S, "5.4", 3, "Let WithCancellation(token) reach the async iterator.", "async IAsyncEnumerable<int> Ticks([____] CancellationToken token = default)", ["EnumeratorCancellation"], "Without it the caller's token is silently ignored (warning CS8425).")
mc(S, "5.4", 3, "A streaming endpoint (returns IAsyncEnumerable) fails halfway. The client gets...", ["500", "200, then a cut-off body", "404", "Nothing"], 1, "The 200 was already sent with the first items. Check errors before streaming.")
mc(S, "5.4", 2, "EF Core AsAsyncEnumerable() vs ToListAsync():", ["Same", "Rows handled one at a time vs all loaded into a list first", "AsAsyncEnumerable is synchronous", "ToListAsync streams"], 1, "Memory stays flat for big tables.")
tf(S, "5.4", 2, ".NET 10 has LINQ for IAsyncEnumerable built in (Where, Select, ToListAsync) without a package.", True, "System.Linq.AsyncEnumerable; earlier versions needed System.Linq.Async.")
out(S, "5.4", 3, "async IAsyncEnumerable<int> Ticks()\n{\n    await Task.Delay(1);\n    yield return 1;\n}\nvar ticks = Ticks();\nConsole.WriteLine(\"made\");", ["made", "1 made", "Nothing until awaited", "Compile error"], 0, "Like normal iterators, nothing runs until something loops over it.")

# ---------------- Section 6: Database, State & Error Handling ----------------
S = 6
mc(S, "6.1", 2, "The N+1 query problem is...", ["One query too many", "Loading a list (1 query) then each item's related data (N more queries)", "A SQL syntax error", "A missing index"], 1, "6.1 logs the SQL: lazy loading in a loop sends one query per book.")
blank(S, "6.1", 1, "Load each book's author in the same query.", "database.Books.____(book => book.Author)", ["Include"], "Include adds a JOIN; ThenInclude goes one level deeper.")
blank(S, "6.1", 2, "Load the author's profile too.", "database.Books\n    .Include(book => book.Author)\n    .____(author => author.Profile)", ["ThenInclude"], "ThenInclude continues from the previous Include.")
mc(S, "6.1", 2, "AsNoTracking() is good for...", ["Saving changes", "Read-only queries: faster, EF doesn't watch the objects", "Deleting", "Migrations"], 1, "Tracked objects cost memory and time; a list page doesn't need them.")
mc(S, "6.2", 2, "Two SaveChanges calls that must both succeed or both fail need...", ["Two DbContexts", "A transaction: BeginTransactionAsync + CommitAsync", "AsNoTracking", "Nothing, EF does it"], 1, "One SaveChanges is already one transaction; several need an explicit one.")
blank(S, "6.2", 2, "Start an explicit transaction.", "await using var transaction = await database.Database.____();", ["BeginTransactionAsync"], "Commit with CommitAsync; disposing without commit rolls back.")
mc(S, "6.2", 3, "TransactionScope with EF Core on SQLite...", ["Works fine", "Throws: SQLite doesn't support ambient transactions", "Is ignored silently", "Commits twice"], 1, "6.2 found EF refuses (AmbientTransactionWarning as an error).")
mc(S, "6.2", 2, "A soft delete...", ["Removes the row", "Marks the row deleted (IsDeleted) and hides it with a query filter", "Moves it to another database", "Is a SQL command"], 1, "The data stays for audits/undo; HasQueryFilter hides it.")
mc(S, "6.3", 2, "IOptions vs IOptionsSnapshot vs IOptionsMonitor: which sees settings changes while the app runs, even in a singleton?", ["IOptions", "IOptionsSnapshot", "IOptionsMonitor", "None"], 2, "IOptions reads once; Snapshot once per request (scoped); Monitor always current.")
mc(S, "6.3", 3, "A cache stampede is...", ["A full cache", "Many requests missing the cache at once and all hitting the database", "A memory leak", "A cache with no expiry"], 1, "HybridCache (6.3) lets only one caller rebuild the value.")
mc(S, "6.4", 2, "Session data in ASP.NET Core is stored...", ["In the cookie itself", "On the server, found by an id in a cookie", "In the URL", "In localStorage"], 1, "6.4 stores the cart as JSON in session.")
blank(S, "6.4", 2, "Enable sessions in Program.cs (middleware).", "app.____();", ["UseSession"], "Plus builder.Services.AddSession() and a distributed cache.")
mc(S, "6.5", 2, "Which handles every unhandled exception centrally in ASP.NET Core 8+?", ["try/catch everywhere", "IExceptionHandler + UseExceptionHandler", "Response.StatusCode = 500", "A finally block"], 1, "One place turns exceptions into ProblemDetails responses.")
mc(S, "6.5", 2, "ProblemDetails is...", ["A logging library", "A standard JSON shape for HTTP errors (type, title, status, detail)", "A database table", "An exception type"], 1, "Content-Type application/problem+json (RFC 9457).")
tf(S, "6.5", 2, "Showing stack traces to users in Production is fine.", False, "They leak internals; show a friendly page and log the details.")
mc(S, "6.6", 2, "FromSql($\"SELECT * FROM Products WHERE Name = {name}\") is safe because...", ["It escapes quotes", "The interpolated value becomes a SQL parameter", "Names can't contain SQL", "It isn't safe"], 1, "FromSqlRaw with string concatenation would be injectable.")
mc(S, "6.6", 2, "ExecuteUpdateAsync(...) does what?", ["Loads rows, changes them, saves", "Sends one UPDATE statement without loading rows", "Updates the model", "Runs a migration"], 1, "Bulk update in one statement; tracked objects aren't updated.")
mc(S, "6.6", 3, "A concurrency token makes SaveChanges throw when...", ["The table is empty", "Someone else changed the row since you loaded it", "Two contexts exist", "The token is null"], 1, "DbUpdateConcurrencyException instead of last-write-wins.")
blank(S, "6.6", 2, "Delete all discontinued products in one statement.", "await database.Products.Where(p => p.Discontinued).____();", ["ExecuteDeleteAsync"], "One DELETE; no objects loaded.")
mc(S, "6.7", 2, "IEntityTypeConfiguration<T> is for...", ["Queries", "Putting one entity's database setup in its own class", "Migrations", "Validation"], 1, "Applied with modelBuilder.ApplyConfiguration(new ProductConfiguration()).")
blank(S, "6.7", 2, "Apply every configuration class in the assembly.", "modelBuilder.____(typeof(ShopDbContext).Assembly);", ["ApplyConfigurationsFromAssembly"], "No list to maintain, but it applies configurations meant for other contexts too.")
mc(S, "6.7", 2, "Table-per-hierarchy means...", ["A table per class", "All subclasses in ONE table with a discriminator column", "No inheritance", "A view per class"], 1, "HasDiscriminator<string>(\"Type\").HasValue<Material>(\"Material\")...")
mc(S, "6.7", 2, "OfType<MaterialModel>() on a table-per-hierarchy set becomes...", ["A JOIN", "WHERE Type = 'Material'", "A UNION", "An in-memory filter"], 1, "With table-per-type it would be a JOIN instead.")
mc(S, "6.7", 2, "A shadow property is...", ["A private field", "A column EF maps that the C# class doesn't have", "A computed property", "A deleted column"], 1, "builder.Property<int>(\"Id\") + HasKey(\"Id\").")
mc(S, "6.7", 3, "EF.Property<int>(invoice, \"Id\") on an already-loaded object...", ["Returns the id", "Throws: it only works inside a LINQ query", "Returns 0", "Loads it again"], 1, "Use database.Entry(invoice).Property<int>(\"Id\").CurrentValue instead.")
blank(S, "6.7", 2, "Always load the lines with every invoice.", "builder.Navigation(\"linesCollection\").____();", ["AutoInclude"], "Turn it off for one query with IgnoreAutoIncludes().")
mc(S, "6.7", 3, "IgnoreAutoIncludes() alone, after the same DbContext already loaded Acme's lines, returns Acme with...", ["0 lines", "the 3 lines it loaded earlier", "an exception", "null"], 1, "Tracked objects get attached to each other. Add AsNoTracking() for a list page.")
mc(S, "6.7", 3, "Why expose a private list as linesCollection.AsReadOnly() instead of IEnumerable?", ["Faster", "IEnumerable over the List can be cast back to List<T> and changed", "EF needs it", "No difference"], 1, "AsReadOnly throws NotSupportedException on Add and can't be cast back.")
mc(S, "6.7", 3, "With no Invoices DbSet, what did EF name the invoice table?", ["Invoices", "InvoiceModel", "Invoice", "dbo.Invoices"], 1, "Table names come from DbSet property names; otherwise the class name. Use ToTable(\"Invoices\").")
tf(S, "6.7", 2, "OfType + Join + GroupBy with a Sum can run as ONE SQL command.", True, "6.7's report: WHERE Type='Material', INNER JOIN, GROUP BY with SUM.")
